tasks.solution:
function safeParse(text) {
  // JSON.parse'ı try/catch içine al; hata olursa null döndür
  try {
    return JSON.parse(text);
  } catch (error) {
    return null;
  }
}

console.log(safeParse('{"skor": 42}'));
console.log(safeParse("{bozuk"));

check.js:
assert(same(safeParse('{"a": 1}'), { a: 1 }), "Geçerli JSON okunup döndürülmeli.");
assert(same(safeParse("[1, 2]"), [1, 2]), "Diziler de okunmalı.");
let broken;
try {
  broken = safeParse("{bozuk");
} catch (e) {
  assert(false, "safeParse bozuk metinde hata fırlatmamalı; try/catch ile yakalayıp null döndürmeli.");
}
assert(broken === null, "Bozuk metin için null dönmeli.");
let empty;
try {
  empty = safeParse("");
} catch (e) {
  assert(false, "Boş metinde de hata fırlatmamalı.");
}
assert(empty === null, "Boş metin için de null dönmeli.");

