tasks.solution:
function launch(ok) {
  const steps = [];
  // try / catch / finally
  try {
    if (!ok) throw new Error("Motor arızası");
    steps.push("Kalkış başarılı");
  } catch (error) {
    steps.push("Sorun: " + error.message);
  } finally {
    steps.push("Panel kapatıldı");
  }
  return steps;
}

console.log(launch(true));
console.log(launch(false));

