project_task.solution:
const DEFAULT_SAVE = { best: 0, level: 1 };

function loadSave() {
  const text = localStorage.getItem("yildizSave");
  // JSON.parse'ı try/catch ile güvenli yap
  if (text === null) return { ...DEFAULT_SAVE };
  try {
    return JSON.parse(text);
  } catch (error) {
    console.warn("Kayıt bozuk, sıfırdan başlıyoruz.");
    return { ...DEFAULT_SAVE };
  }
}

const save = loadSave();
document.querySelector("#info").textContent = `En iyi: ${save.best} · Seviye: ${save.level}`;

check.js:
const SEED = '{"best": 42, "level": ';
try {
  const info = $("#info").textContent;
  assert(new RegExp("En iyi:\\s*" + save.best + "\\b").test(info) && new RegExp("Seviye:\\s*" + save.level + "\\b").test(info), "#info açılışta kaydı 'En iyi: 0 · Seviye: 1' biçiminde göstermeli.");
  localStorage.setItem("yildizSave", JSON.stringify({ best: 42, level: 3 }));
  assert(same(loadSave(), { best: 42, level: 3 }), "Kayıt sağlamsa okunan nesne ({ best: 42, level: 3 }) döndürülmeli.");
  localStorage.setItem("yildizSave", "bozuk{");
  const before = out().length;
  let broken;
  try {
    broken = loadSave();
  } catch (e) {
    assert(false, "Bozuk kayıtta loadSave() hata fırlatmamalı; try/catch ile yakala.");
  }
  assert(same(broken, { best: 0, level: 1 }), "Bozuk kayıtta { best: 0, level: 1 } döndürülmeli.");
  assert(/Kayıt bozuk/.test(out().slice(before)), "Bozuk kayıtta console.warn ile 'Kayıt bozuk, sıfırdan başlıyoruz.' yazılmalı.");
  localStorage.removeItem("yildizSave");
  const none = loadSave();
  assert(same(none, { best: 0, level: 1 }), "Kayıt hiç yoksa (null) da { best: 0, level: 1 } döndürülmeli.");
} finally {
  localStorage.setItem("yildizSave", SEED);
}

