project_task.solution:
function validateContact(data) {
  // üç kontrol; hatalıysa throw new Error(...)
  if (data.name === "") throw new Error("Adını yazmalısın.");
  if (!data.email.includes("@")) throw new Error("E-posta adresi geçersiz.");
  if (data.message.length < 10) throw new Error("Mesaj en az 10 karakter olmalı.");
}

const form = document.querySelector("#contact");
form.addEventListener("submit", (e) => {
  e.preventDefault();
  const data = {
    name: document.querySelector("#name").value.trim(),
    email: document.querySelector("#email").value.trim(),
    message: document.querySelector("#message").value.trim(),
  };
  const error = document.querySelector("#error");
  const status = document.querySelector("#status");
  // try / catch ile doğrula ve sonucu göster
  try {
    validateContact(data);
    error.textContent = "";
    status.textContent = "Mesajın gönderildi, teşekkürler!";
  } catch (err) {
    error.textContent = err.message;
    status.textContent = "";
  }
});

check.js:
const messageOf = (data) => {
  try {
    validateContact(data);
    return null;
  } catch (e) {
    return e.message;
  }
};
assert(messageOf({ name: "Ada", email: "ada@site.com", message: "Merhaba, siten çok güzel!" }) === null, "Geçerli veride hata fırlatılmamalı.");
assert(messageOf({ name: "", email: "a@b", message: "0123456789" }) === "Adını yazmalısın.", "Ad boşsa 'Adını yazmalısın.' hatası fırlatılmalı.");
assert(messageOf({ name: "Ada", email: "ada.site.com", message: "0123456789" }) === "E-posta adresi geçersiz.", "E-postada @ yoksa 'E-posta adresi geçersiz.' hatası fırlatılmalı.");
assert(messageOf({ name: "Ada", email: "ada@site.com", message: "kısa" }) === "Mesaj en az 10 karakter olmalı.", "Mesaj 10 karakterden kısaysa 'Mesaj en az 10 karakter olmalı.' hatası fırlatılmalı.");
type("#name", "Ada");
type("#email", "ada-site.com");
type("#message", "Merhaba dünya!");
submit("#contact");
assert($("#error").textContent.trim() === "E-posta adresi geçersiz.", "Hatalı formda hata mesajı #error'da görünmeli.");
assert(!/gönderildi/.test($("#status").textContent), "Hata varsa 'gönderildi' mesajı görünmemeli.");
type("#email", "ada@site.com");
submit("#contact");
assert($("#error").textContent.trim() === "", "Form düzelince #error boşalmalı.");
assert($("#status").textContent.trim() === "Mesajın gönderildi, teşekkürler!", "#status 'Mesajın gönderildi, teşekkürler!' yazmalı.");
type("#message", "kısa");
submit("#contact");
assert($("#error").textContent.trim() === "Mesaj en az 10 karakter olmalı." && $("#status").textContent.trim() === "", "Yeni bir hatada #error mesajı göstermeli, #status boşalmalı.");

