project_task.solution:
const rows = [
  '{"title": "Fizik tekrarı", "minutes": 30}',
  '{bozuk',
  '{"title": "", "minutes": 20}',
  '{"title": "Tarih", "minutes": -5}',
  '{"title": "Kimya", "minutes": 45}',
];

function cleanTasks(rows) {
  const tasks = [];
  // her satırı oku ve kontrol et
  let skipped = 0;
  for (const row of rows) {
    try {
      const task = JSON.parse(row);
      const titleOk = typeof task.title === "string" && task.title.trim() !== "";
      const minutesOk = typeof task.minutes === "number" && task.minutes > 0;
      if (titleOk && minutesOk) {
        tasks.push(task);
      } else {
        skipped++;
      }
    } catch (error) {
      skipped++;
    }
  }
  document.querySelector("#warning").textContent = skipped > 0 ? `${skipped} kayıt atlandı` : "";
  return tasks;
}

function render(tasks) {
  const list = document.querySelector("#list");
  list.innerHTML = "";
  for (const t of tasks) {
    const li = document.createElement("li");
    li.textContent = `${t.title} (${t.minutes} dk)`;
    list.append(li);
  }
}

render(cleanTasks(rows));

check.js:
assert($$("#list li").length === 2, "Açılışta yalnızca 2 geçerli görev listelenmeli.");
assert(/3 kayıt atlandı/.test($("#warning").textContent), "#warning '3 kayıt atlandı' yazmalı.");
let r;
try {
  r = cleanTasks(['{"title": "A", "minutes": 5}', "[1", '{"title": "B", "minutes": "10"}', '{"minutes": 15}']);
} catch (e) {
  assert(false, "cleanTasks bozuk metinlerde hata fırlatmamalı: " + e.message);
}
assert(same(r, [{ title: "A", minutes: 5 }]), "Yalnızca geçerli görevler döndürülmeli (minutes metin olamaz, title olmalı).");
assert($("#warning").textContent.trim() === "3 kayıt atlandı", "Atlanan sayısı hesaplanmalı: '3 kayıt atlandı'.");
const ok = cleanTasks(['{"title": "C", "minutes": 1}']);
assert(ok.length === 1 && $("#warning").textContent.trim() === "", "Hiç kayıt atlanmadıysa #warning boş olmalı.");

