project_task.solution:
const packText = JSON.stringify([
  { soru: "Ay, hangi gezegenin uydusudur?", secenekler: ["Mars", "Dünya", "Jüpiter"], dogru: 1 },
  { soru: "Kızıl gezegen hangisidir?", secenekler: "Mars", dogru: 0 },
  { soru: "Halkalarıyla ünlü gezegen hangisidir?", secenekler: ["Satürn", "Mars"], dogru: 0 },
  { soru: "Güneşe en yakın gezegen hangisidir?", secenekler: ["Venüs", "Merkür"], dogru: 5 },
  { soru: "En büyük gezegen hangisidir?", secenekler: ["Satürn", "Jüpiter", "Neptün"], dogru: 1 },
]);

function isValid(q) {
  return typeof q.soru === "string" && q.soru.trim() !== "" &&
    Array.isArray(q.secenekler) && q.secenekler.length >= 2 &&
    Number.isInteger(q.dogru) && q.dogru >= 0 && q.dogru < q.secenekler.length;
}

function loadPack(text) {
  // oku (try/catch), geçerlileri süz, uyarıyı yaz
  const warning = document.querySelector("#warning");
  let data;
  try {
    data = JSON.parse(text);
  } catch (error) {
    warning.textContent = "Soru paketi okunamadı.";
    return [];
  }
  const valid = data.filter(isValid);
  const skipped = data.length - valid.length;
  warning.textContent = skipped > 0 ? `${skipped} soru atlandı` : "";
  return valid;
}

const questions = loadPack(packText);
document.querySelector("#pack-info").textContent = `${questions.length} soru hazır`;

check.js:
assert($("#pack-info").textContent.trim() === "3 soru hazır", "Paketteki 3 geçerli soru tutulmalı: #pack-info '3 soru hazır' yazmalı.");
assert($("#warning").textContent.trim() === "2 soru atlandı", "#warning '2 soru atlandı' yazmalı.");
let r;
try {
  r = loadPack("{bozuk");
} catch (e) {
  assert(false, "loadPack bozuk metinde hata fırlatmamalı; try/catch ile yakala.");
}
assert(same(r, []), "Okunamayan pakette boş dizi dönmeli.");
assert($("#warning").textContent.trim() === "Soru paketi okunamadı.", "#warning 'Soru paketi okunamadı.' yazmalı.");
const one = loadPack(JSON.stringify([{ soru: "A?", secenekler: ["x", "y"], dogru: 1 }]));
assert(one.length === 1 && $("#warning").textContent.trim() === "", "Hiç soru atlanmadıysa #warning boş olmalı.");
const mixed = loadPack(JSON.stringify([
  { soru: "", secenekler: ["x", "y"], dogru: 0 },
  { soru: "B?", secenekler: ["x"], dogru: 0 },
  { soru: "C?", secenekler: ["x", "y", "z"], dogru: 2 },
  { soru: "D?", secenekler: ["x", "y"], dogru: -1 },
]));
assert(mixed.length === 1 && mixed[0].soru === "C?", "Boş soru, tek seçenek ve geçersiz dogru değerleri atlanmalı.");
assert($("#warning").textContent.trim() === "3 soru atlandı", "#warning '3 soru atlandı' yazmalı.");
